51|     position: absolute;
52|     top: 14px;
53|     left: 14px;
54|     color: #0078bf;
55|     font-weight: bold;
56|     font-size: 22px;
57|     letter-spacing: 1px;
58|     z-index: 10;
59|     text-shadow: 1px 1px 0 #ff48b0;
60|   }
61| </style>
62| </head>
63| <body>
64| <div id="wrap">
65|   <canvas id="game"></canvas>
66|   <div id="tally">POPS: 0</div>
67|   <button id="clearBtn">Clear</button>
68| </div>
69| <script>
70| // ---- Bridge helper (verbatim) ----
71| const CARTRIDGE = {
72|   send(type, payload = {}) {
73|     window.parent.postMessage(
74|       { source: "cartridge", v: 1, type, payload },
75|       "*",
76|     );
77|   },
78| };
79| </script>
80| <script>
81| (function () {
82|   const canvas = document.getElementById("game");
83|   const ctx = canvas.getContext("2d");
84|   const clearBtn = document.getElementById("clearBtn");
85|   const tallyEl = document.getElementById("tally");
86| 
87|   let dpr = Math.max(1, window.devicePixelRatio || 1);
88|   let W = 0, H = 0;
89| 
90|   function resize() {
91|     W = window.innerWidth;
92|     H = window.innerHeight;
93|     canvas.width = Math.floor(W * dpr);
94|     canvas.height = Math.floor(H * dpr);
95|     canvas.style.width = W + "px";
96|     canvas.style.height = H + "px";
97|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
98|     if (!grainTile) buildGrain();
99|   }
100|   window.addEventListener("resize", resize);
101| 
102|   // ---- Grain tile (pre-rendered noise) ----
103|   let grainTile = null;
104|   function buildGrain() {
105|     const size = 128;
106|     const gCanvas = document.createElement("canvas");
107|     gCanvas.width = size;
108|     gCanvas.height = size;
109|     const gctx = gCanvas.getContext("2d");
110|     const imgData = gctx.createImageData(size, size);
111|     for (let i = 0; i < imgData.data.length; i += 4) {
112|       const v = Math.random() * 255;
113|       imgData.data[i] = v;
114|       imgData.data[i + 1] = v;
115|       imgData.data[i + 2] = v;
116|       imgData.data[i + 3] = 255;
117|     }
118|     gctx.putImageData(imgData, 0, 0);
119|     grainTile = gCanvas;
120|   }
121| 
122|   // ---- Colours ----
123|   const PAPER = "#fbf7ee";
124|   const INK1 = "#ff48b0";
125|   const INK2 = "#0078bf";
126|   const OVERLAP = "#5b3a8c";
127| 
128|   // ---- State ----
129|   const pieces = []; // bubbles: {x,y,r,vx,vy,color,popped,popT}
130|   let tally = 0;
131|   let paused = false;
132|   let running = false; // becomes true after first tap
133|   let hintPulse = 0;
134| 
135|   function rand(a, b) {
136|     return a + Math.random() * (b - a);
137|   }
138| 
139|   function spawnBatch(n) {
140|     for (let i = 0; i < n; i++) {
141|       spawnOne();
142|     }
143|   }
144| 
145|   function spawnOne() {
146|     const r = rand(24, 48);
147|     const x = rand(r, W - r);
148|     const y = rand(r, H - r);
149|     const color = Math.random() < 0.5 ? INK1 : INK2;
150|     pieces.push({
151|       x, y, r,
152|       vx: rand(-18, 18),
153|       vy: rand(-14, 14),
154|       color,
155|       born: performance.now(),
156|       popped: false,
157|       popT: 0,
158|     });
159|   }
160| 
161|   function maintainBubbles() {
162|     // keep a healthy count of live bubbles
163|     const alive = pieces.filter((p) => !p.popped);
164|     if (alive.length < 9) {
165|       spawnOne();
166|     }
167|   }
168| 
169|   function settle(list, dt) {
170|     for (const p of list) {
171|       if (p.popped) {
172|         p.popT += dt;
173|         continue;
174|       }
175|       p.x += p.vx * dt;
176|       p.y += p.vy * dt;
177|       if (p.x - p.r < 0) { p.x = p.r; p.vx *= -1; }
178|       if (p.x + p.r > W) { p.x = W - p.r; p.vx *= -1; }
179|       if (p.y - p.r < 0) { p.y = p.r; p.vy *= -1; }
180|       if (p.y + p.r > H) { p.y = H - p.r; p.vy *= -1; }
181|     }
182|     // remove fully-popped bubbles after their animation
183|     for (let i = pieces.length - 1; i >= 0; i--) {
184|       if (pieces[i].popped && pieces[i].popT > 0.28) {
185|         pieces.splice(i, 1);
186|       }
187|     }
188|     maintainBubbles();
189|   }
190| 
191|   function popAt(x, y) {
192|     // find topmost unpopped bubble under point
193|     for (let i = pieces.length - 1; i >= 0; i--) {
194|       const p = pieces[i];
195|       if (p.popped) continue;
196|       const dx = x - p.x, dy = y - p.y;
197|       if (dx * dx + dy * dy <= p.r * p.r) {
198|         p.popped = true;
199|         p.popT = 0;
200|         tally += 1;
201|         tallyEl.textContent = "POPS: " + tally;
202|         CARTRIDGE.send("score", { value: tally });
203|         return true;
204|       }
205|     }
206|     return false;
207|   }
208| 
209|   // Single clear-the-table function: used by the visible button AND by
210|   // the host "reset" command. Both call this exact function.
211|   function clearTable() {
212|     pieces.length = 0;
213|     tally = 0;
214|     running = false;
215|     tallyEl.textContent = "POPS: 0";
216|     CARTRIDGE.send("score", { value: 0 });
217|     spawnBatch(10);
218|     draw();
219|   }
220| 
221|   // ---- Drawing ----
222|   function drawBackground() {
223|     ctx.fillStyle = PAPER;
224|     ctx.fillRect(0, 0, W, H);
225|   }
226| 
227|   function drawHalftoneShade(cx, cy, r, color) {
228|     // subtle halftone dots to fake shading on bubble edge
229|     ctx.save();
230|     ctx.globalAlpha = 0.35;
231|     ctx.fillStyle = color;
232|     const dotCount = 10;
233|     for (let i = 0; i < dotCount; i++) {
234|       const ang = (i / dotCount) * Math.PI * 2;
235|       const dr = r * 0.72;
236|       const dx = cx + Math.cos(ang) * dr;
237|       const dy = cy + Math.sin(ang) * dr;
238|       const rad = Math.max(1, r * 0.06);
239|       ctx.beginPath();
240|       ctx.arc(dx, dy, rad, 0, Math.PI * 2);
241|       ctx.fill();
242|     }
243|     ctx.restore();
244|   }
245| 
246|   function drawBubble(p) {
247|     if (p.popped) {
248|       // pop burst animation: expanding ring fragments
249|       const t = p.popT / 0.28;
250|       const alpha = Math.max(0, 1 - t);
251|       ctx.save();
252|       ctx.globalAlpha = alpha;
253|       ctx.strokeStyle = p.color === INK1 ? INK2 : INK1;
254|       ctx.lineWidth = 3;
255|       const spokes = 8;
256|       const dist = p.r * (0.6 + t * 0.9);
257|       for (let i = 0; i < spokes; i++) {
258|         const ang = (i / spokes) * Math.PI * 2;
259|         const x1 = p.x + Math.cos(ang) * p.r * 0.3;
260|         const y1 = p.y + Math.sin(ang) * p.r * 0.3;
261|         const x2 = p.x + Math.cos(ang) * dist;
262|         const y2 = p.y + Math.sin(ang) * dist;
263|         ctx.beginPath();
264|         ctx.moveTo(x1, y1);
265|         ctx.lineTo(x2, y2);
266|         ctx.stroke();
267|       }
268|       ctx.restore();
269|       return;
270|     }
271| 
272|     // misregistration offset layer (second ink offset by 2px)
273|     const otherColor = p.color === INK1 ? INK2 : INK1;
274| 
275|     ctx.save();
276|     ctx.globalAlpha = 0.9;
277|     ctx.fillStyle = otherColor;
278|     ctx.beginPath();
279|     ctx.arc(p.x + 2, p.y + 1.5, p.r, 0, Math.PI * 2);
280|     ctx.fill();
281|     ctx.restore();
282| 
283|     ctx.save();
284|     ctx.globalAlpha = 0.92;
285|     ctx.fillStyle = p.color;
286|     ctx.beginPath();
287|     ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
288|     ctx.fill();
289|     ctx.restore();
290| 
291|     drawHalftoneShade(p.x, p.y, p.r, otherColor);
292| 
293|     // outline in overlap ink
294|     ctx.save();
295|     ctx.strokeStyle = OVERLAP;
296|     ctx.lineWidth = 2;
297|     ctx.beginPath();
298|     ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
299|     ctx.stroke();
300|     ctx.restore();
301| 
302|     // highlight dot
303|     ctx.save();
304|     ctx.fillStyle = PAPER;
305|     ctx.globalAlpha = 0.85;
306|     ctx.beginPath();
307|     ctx.arc(p.x - p.r * 0.35, p.y - p.r * 0.35, p.r * 0.18, 0, Math.PI * 2);
308|     ctx.fill();
309|     ctx.restore();
310|   }
311| 
312|   function drawGrain() {
313|     if (!grainTile) return;
314|     ctx.save();
315|     ctx.globalAlpha = 0.08;
316|     const pattern = ctx.createPattern(grainTile, "repeat");
317|     ctx.fillStyle = pattern;
318|     ctx.fillRect(0, 0, W, H);
319|     ctx.restore();
320|   }
321| 
322|   function drawTitleHint() {
323|     hintPulse += 0.05;
324|     const alpha = 0.55 + 0.45 * Math.sin(hintPulse);
325|     ctx.save();
326|     ctx.globalAlpha = alpha;
327|     ctx.fillStyle = OVERLAP;
328|     ctx.font = "bold " + Math.min(38, W * 0.08) + "px 'Arial Narrow', Arial, sans-serif";
329|     ctx.textAlign = "center";
330|     ctx.textBaseline = "middle";
331|     ctx.fillText("TAP TO BEGIN", W / 2, H / 2);
332|     ctx.restore();
333| 
334|     ctx.save();
335|     ctx.fillStyle = INK1;
336|     ctx.font = "bold " + Math.min(26, W * 0.06) + "px 'Arial Narrow', Arial, sans-serif";
337|     ctx.textAlign = "center";
338|     ctx.fillText("POP THE BUBBLES", W / 2, H / 2 - 50);
339|     ctx.restore();
340|   }
341| 
342|   function draw() {
343|     drawBackground();
344|     for (const p of pieces) drawBubble(p);
345|     if (!running) drawTitleHint();
346|     drawGrain();
347|   }
348| 
349|   // ---- Loop ----
350|   let lastTime = performance.now();
351|   function frame(now) {
352|     const dt = Math.min(0.05, (now - lastTime) / 1000);
353|     lastTime = now;
354|     if (!paused && running) {
355|       settle(pieces, dt);
356|     }
357|     draw();
358|     requestAnimationFrame(frame);
359|   }
360| 
361|   // ---- Input ----
362|   canvas.style.touchAction = "none";
363|   canvas.addEventListener("pointerdown", (event) => {
364|     event.preventDefault();
365|     if (paused) return;
366|     const rect = canvas.getBoundingClientRect();
367|     const x = event.clientX - rect.left;
368|     const y = event.clientY - rect.top;
369|     if (!running) {
370|       running = true;
371|       CARTRIDGE.send("start");
372|       return;
373|     }
374|     popAt(x, y);
375|   });
376| 
377|   // Visible in-game control: calls the same clearTable() function used by reset.
378|   clearBtn.addEventListener("click", (e) => {
379|     e.stopPropagation();
380|     clearTable();
381|   });
382|   clearBtn.addEventListener("pointerdown", (e) => {
383|     e.stopPropagation();
384|   });
385| 
386|   // ---- Host bridge commands ----
387|   window.addEventListener("message", (event) => {
388|     const data = event.data;
389|     if (!data || data.source !== "cartridge-host") return;
390|     if (data.type === "pause") paused = true;
391|     if (data.type === "resume") paused = false;
392|     if (data.type === "reset") clearTable();
393|   });
394| 
395|   // ---- Boot ----
396|   resize();
397|   spawnBatch(10);
398|   draw();
399|   CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
400|   requestAnimationFrame(frame);
401| })();
402| </script>
403| </body>
404| </html>
405|

